// Phase 2: route a classified inbox row to its target table.
const __helpers = this.helpers;
async function __req(opts) { return __helpers.httpRequest({ ...opts, returnFullResponse: false }); }
const input = $input.first().json;
const body = input.body || input;
const inbox_id = body.inbox_id;
if (!inbox_id) throw new Error('inbox_id required');

const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SB_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdvanBmZnNyeHliYnBiZHp6cnZzIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NjE3NzA2MywiZXhwIjoyMDkxNzUzMDYzfQ.QU6yz1uhH01U-Dcomd4DoPsGZmxYHh29K4bCOmfAKZc';
const H = { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json' };
const Hrep = { ...H, 'Prefer': 'return=representation' };
const Hmin = { ...H, 'Prefer': 'return=minimal' };

const rows = await __req({ method: 'GET', url: `${SUPA}/rest/v1/tasks_inbox?id=eq.${inbox_id}&select=*`, headers: H, json: true });
const row = (rows || [])[0];
if (!row) throw new Error('inbox row not found');
const cls = row.classification || {};
const rawText = row.raw_text || '';
const firstAction = cls.first_action || rawText.slice(0, 200);
const agent = cls.primary_agent || 'agatha';
const targetTable = cls.target_table || 'tasks';

// Compute concept_id via RPC.
async function conceptSlug(text) {
  try {
    const r = await __req({ method: 'POST', url: `${SUPA}/rest/v1/rpc/compute_concept_slug`, headers: H, body: { p_text: text }, json: true });
    return typeof r === 'string' ? r : (r && r.compute_concept_slug) || null;
  } catch { return null; }
}
const concept_id = cls.suggested_concept_id || await conceptSlug(firstAction);

function firstWord(t) { return (t || '').trim().split(/\s+/)[0] || ''; }
function headTitle(t) { return (t || '').replace(/\s+/g, ' ').trim().slice(0, 80); }

let target_id = null;
let target_table = targetTable;
let routed_to_agent = agent;
let failure = null;

try {
  if (targetTable === 'leads') {
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/leads`, headers: Hrep, body: {
      full_name: headTitle(rawText), status: 'new', assignee_agent: agent,
      why_relevant: firstAction, source: 'inbox',
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
  } else if (targetTable === 'visibility_targets') {
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/visibility_targets`, headers: Hrep, body: {
      title: headTitle(firstAction), status: 'queued', type: 'speaking',
      why_relevant: firstAction,
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
    routed_to_agent = 'nova';
  } else if (targetTable === 'guests') {
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/guests`, headers: Hrep, body: {
      name: headTitle(rawText), status: 'scouted', one_liner: firstAction,
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
    routed_to_agent = 'nell';
  } else if (targetTable === 'content_ideas') {
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/content_ideas`, headers: Hrep, body: {
      idea: headTitle(firstAction), source_snippet: rawText, source_url: null,
      state: 'seeded', source_type: 'inspiration_sweep',
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
    routed_to_agent = 'cleo';
  } else if (targetTable === 'bets') {
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/bets`, headers: Hrep, body: {
      title: headTitle(firstAction), hypothesis: rawText, status: 'live', kind: 'general',
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
    routed_to_agent = 'marcus';
  } else if (targetTable === 'customers') {
    // No direct customer create. Create a task linked back via raw_text.
    target_table = 'tasks';
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/tasks`, headers: Hrep, body: {
      title: 'Customer follow-up: ' + headTitle(firstAction), agent, status: 'waiting',
      workstream: 'customer_acquisition', description: rawText, krish_reviewed: false,
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
  } else {
    // tasks (and the unknown-bucket fallthrough)
    target_table = 'tasks';
    const ins = await __req({ method: 'POST', url: `${SUPA}/rest/v1/tasks`, headers: Hrep, body: {
      title: headTitle(firstAction), agent, status: 'waiting',
      workstream: cls.task_type === 'content_idea' ? 'content' : 'general',
      description: rawText, krish_reviewed: false,
    }, json: true });
    target_id = (ins && ins[0] && ins[0].id) || null;
  }
} catch (e) { failure = (e.message || String(e)).slice(0, 250); }

const patch = failure ? {
  status: 'failed', archive_reason: 'classifier_failed', archived_at: new Date().toISOString(),
} : {
  status: 'in_flight', target_table, target_id, routed_to_agent, concept_id,
};
await __req({ method: 'PATCH', url: `${SUPA}/rest/v1/tasks_inbox?id=eq.${inbox_id}`, headers: Hmin, body: patch, json: true });

const telegram_text = failure
  ? `Inbox router failed: ${failure}`
  : `Inbox routed to ${routed_to_agent}. "${headTitle(firstAction)}". Will return when it needs you.`;

return [{ json: { ok: !failure, inbox_id, target_table, target_id, routed_to_agent, telegram_text } }];
